  'Deze afbeelding naar het AI-model sturen?':
      'Odeslat tento obrázek do modelu AI?',
  'De afbeelding gaat ongewijzigd naar': 'Obrázek bude beze změny odeslán na',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck v obrázku nic nezačerňuje: tváře, text na snímku obrazovky a viditelné údaje odejdou s ním.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Kontrola obrázků zde našla jednu nebo více rozpoznatelných tváří.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Vedle exportu vzniknou dva soubory, díky nimž si příjemce může začernění ověřit.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'vypisuje, co bylo vynecháno, bez samotných hodnot. Tento soubor může jít se zprávou.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'obsahuje klíče, jimiž lze každou začerněnou hodnotu zpětně dopočítat. Tento soubor neposílejte: začernění by tím bylo zrušeno. Uchovejte jej u zdroje.',
  'slides': 'snímky',
  'Achtergehouden': 'Zadrženo',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Zadrženo: klasifikováno přísněji než prezentace',
  '1 slide achtergehouden door haar TLP': '1 snímek zadržen kvůli svému TLP',
  'slides achtergehouden door hun TLP': 'snímků zadrženo kvůli jejich TLP',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Tyto snímky se nedostanou do prezentace, exportu ani balíčku. Zvyšte úroveň TLP prezentace v Informacích o prezentaci, aby se zahrnuly.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Všechny snímky jsou zadrženy kvůli své klasifikaci TLP, takže není co zobrazit.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Všechny snímky jsou zadrženy kvůli své klasifikaci TLP, takže není co exportovat.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Všechny snímky jsou přeskočeny nebo zadrženy kvůli své klasifikaci TLP, takže není co zobrazit.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Všechny snímky jsou přeskočeny nebo zadrženy kvůli své klasifikaci TLP, takže není co exportovat.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Čísla grafů se neuložila — existují už jen v tomto okně:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'V prohlížeči neexistuje obnova po pádu: zavřete-li tuto kartu, neuložená práce je pryč. Uložte si prezentaci sami.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Místní databáze CVE (stahování spouštíte sami): OciDeck načítá hromadná data přes api.github.com a soubor vydání, na který tato adresa odkazuje.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Vyhledávání CVE (ve výchozím stavu vypnuto): je-li zapnuté, váš hledaný výraz jde na nastavené zrcadlo CVE, a pokud tam nic nenajde, do evropské databáze ENISA a do MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Vložené video z YouTube nebo Vimea načte přehrávač od této služby.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  V prohlížeči: odmítne-li prohlížeč načíst adresu přímo, zkusí to OciDeck přes server, ze kterého aplikace pochází; ta adresa se pak dostane na onen server.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Odvolání nebylo uloženo. Při příštím spuštění bude váš souhlas opět platit.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Nadpis oddílu, který uvádí novou část prezentace. Buďte struční. Přidejte obrázek na pozadí z knihovny obrázků.',
  'Bronnen doorzoeken…': 'Prohledávání zdrojů…',
  'Niet doorzocht': 'Neprohledáno',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Tato kontrola v webové verzi neběží: rozpoznávání obličejů vyžaduje systémovou knihovnu, kterou prohlížeč nemá. Ke kontrole obličejů v obrázcích použijte desktopovou verzi.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Token potřebuje práva pro čtení a zápis do repozitáře. Gitea a Forgejo nemají vyhledávání na serveru; OciDeck hledá lokálně.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Token potřebuje rozsah repo (nebo podrobně: Contents pro čtení a zápis).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Token potřebuje read_repository, write_repository a read_api. Vyhledávání na serveru vyžaduje Advanced nebo Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Rychlé hledání na serveru — kvůli zpoždění indexace může chybět právě změněná sada.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Média se v prostém souboru .md nezachovají',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Obrázky, video a zvuk, které jste v této kartě vybrali, existují jen v paměti. Prostý soubor .md je neuchová — po opětovném otevření budou pryč. Exportujte jako balíček .ocideck, abyste si média vzali s sebou.',
